import{readFileSync,writeFileSync}from'node:fs';import{resolve,join}from'node:path';import{runAnalysisDsl}from'../../../../src/analyze/run-analysis-dsl.ts';
const [boardName,output,codeFile='local-extraction.js']=process.argv.slice(2);if(!['local-extraction.js','section-cache.js'].includes(codeFile))throw Error('known scenario required');if(!['STM32G0_CAN_RS485','TPS63060DSCR','BandAmpV5'].includes(boardName))throw Error('known captured fixture required');
const root=resolve('.'),folder=join(root,'tests','pcb-analyze',boardName);const start=performance.now();
const result=await runAnalysisDsl({board:JSON.parse(readFileSync(join(folder,boardName+'.json'),'utf8')),code:readFileSync(join(folder,codeFile),'utf8')},{timeoutMs:300000,maxOutputBytes:128*1024*1024,maxEntries:10000});
writeFileSync(join(output,'result.json'),JSON.stringify(result));const metadata={status:result.status,wallSeconds:(performance.now()-start)/1000,reports:result.reports.map(r=>({checks:r.checks,plots:r.plots.length})),error:result.error};writeFileSync(join(output,'worker.json'),JSON.stringify(metadata,null,2));console.log(JSON.stringify(metadata));if(result.status!=='complete')process.exitCode=1;
